"""Compare local .env with the VPS .env by hashing values on both sides.

Prints KEY / local hash / vps hash / verdict. Never prints a value.
The VPS fingerprints are read from the file produced by env_fingerprint.sh.
"""
import hashlib
import pathlib
import sys

LOCAL_ENV = pathlib.Path(r"X:\BMJ\.env")
VPS_FP = pathlib.Path(r"X:\BMJ\_captures\qa\vps_env_fp.txt")

# keys whose value is generated by the deployment and must NOT be overwritten from local,
# because the MySQL container was already initialised with them.
DEPLOYMENT_OWNED = {"DB_PASSWORD", "DB_ROOT_PASSWORD"}


def h(val: str) -> str:
    return hashlib.sha256(val.encode("utf-8")).hexdigest()[:12]


local = {}
for line in LOCAL_ENV.read_text(encoding="utf-8", errors="ignore").splitlines():
    line = line.strip()
    if not line or line.startswith("#") or "=" not in line:
        continue
    k, v = line.split("=", 1)
    local[k.strip()] = v.strip()

vps = {}
for line in VPS_FP.read_text(encoding="utf-8", errors="ignore").splitlines():
    parts = line.split()
    if len(parts) == 2:
        vps[parts[0]] = parts[1]

print(f"{'KEY':<26} {'local':<14} {'vps':<14} verdict")
print("-" * 76)
only_local, only_vps, differing, same = [], [], [], []
for k in sorted(set(local) | set(vps)):
    lv, vv = local.get(k), vps.get(k)
    lh = h(lv) if lv is not None else "--"
    if k == "ADMIN_PASSWORD" and lv == "":
        lh = "(empty)"
    if lv is None:
        verdict = "ONLY ON VPS"
        only_vps.append(k)
    elif vv is None:
        verdict = "ONLY LOCAL"
        only_local.append(k)
    elif lh == vv:
        verdict = "same"
        same.append(k)
    else:
        verdict = "DIFFERS"
        differing.append(k)
    if k in DEPLOYMENT_OWNED and verdict == "DIFFERS":
        verdict = "DIFFERS (deployment-owned - keep VPS)"
    print(f"{k:<26} {lh:<14} {vv or '--':<14} {verdict}")

print()
print(f"identical      : {len(same)}")
print(f"differing      : {len(differing)} -> {', '.join(sorted(differing))}")
print(f"only local     : {len(only_local)} -> {', '.join(sorted(only_local))}")
print(f"only on vps    : {len(only_vps)} -> {', '.join(sorted(only_vps))}")

missing = [k for k in ("FAST2SMS_API_KEY", "MAIL_PASSWORD", "WEBHOOK_USERNAME",
                       "WEBHOOK_PASSWORD", "CHARGEBEE_API_KEY") if k not in local]
print(f"critical missing locally: {missing or 'none'}")

empty = [k for k, v in local.items() if v == ""]
print(f"empty values locally    : {empty or 'none'}")
